const result = await tools.image_gen__imagegen({
  prompt: `Create ONE standalone card-theme illustration. Subject: an open padlock resting on a now-empty dice tray, a hand moving a die off the tray toward a nearby cluster of dice. Must keep: the padlock is open and rests on the now-empty locking tray; a hand moves one die from the tray back toward the pool; dice pips coloured exactly as in the subject reference (dark pips stay dark, never recoloured red or blue).
